"""Assemble Week12 .qmd with flat Quarto-safe raw HTML blocks."""
from pathlib import Path
import html
P=Path(__file__).resolve().parents[1]
Q=P/'week12'/'week12.qmd'
head='''---
title: "Statistics for Pharmacists"
subtitle: "Week 12 · Multivariate statistics and machine learning"
author: "Graduate Pharmaceutical Studies"
date: ""
title-slide-attributes:
  data-footer: ""
format:
  revealjs:
    footer: "Statistics 101 · Week 12"
    scrollable: false
    transition: fade
    theme:
      - default
      - ../assets/scss/course.scss
      - ../assets/scss/week12.scss
    resources:
      - figures/**
      - media/**
      - data.js
      - digit_model.js
      - widgets.js
---
'''
slides=[]
def add(t,*body,cls='concept-slide'):
 slides.append(f'## {t} {{.{cls}}}\n\n'+'\n\n'.join(str(b) for b in body if b))
def note(s):return f'<div class="w12-note">{s}</div>'
def eyebrow(s):return f'<div class="w12-eyebrow">{s}</div>'
def formula(s):return f'<div class="w12-formula">{s}</div>'
def figure(name,alt='',tall='',cap=''):
 return f'<div class="w12-figure {tall}"><img src="figures/{name}.svg" alt="{html.escape(alt or name)}"></div>'+(f'<div class="w12-caption">{cap}</div>' if cap else '')
def cards(items):
 rows=[]
 for tag,title,description in items:
  rows.append(f'<div class="w12-card {tag}"><strong>{title}</strong><span>{description}</span></div>')
 return f'<div class="w12-cards" style="--n:{len(items)};">'+''.join(rows)+'</div>'
def flow(items):return f'<div class="w12-flow" style="--n:{len(items)};">'+''.join(f'<div><strong>{h}</strong><span>{b}</span></div>' for h,b in items)+'</div>'
def video(name):return f'<video class="w12-video" controls loop muted playsinline preload="metadata" aria-label="Schematic explanatory animation"><source src="media/{name}.mp4" type="video/mp4">Animation unavailable in this browser.</video>'
def defn(text):return f'<div class="definition-box"><p>{text}</p></div>'
def warn(text):return f'<div class="warning-box"><p>{text}</p></div>'
def quiz(n,q,choices):
 return f'<div class="w12-quiz" data-q="{n}"><div class="w12-quiz-q">{q}</div><div class="w12-choices">'+''.join(f'<button type="button" class="w12-choice" data-choice="{chr(65+i)}">{chr(65+i)}. {v}</button>' for i,v in enumerate(choices))+'<div class="w12-quiz-feedback">Choose one.</div></div></div>'

# OPENING
add('Multivariate statistics &amp; machine learning',eyebrow('Week 12 · final lecture'),'<div class="w12-hero">How do we reason when <strong>many variables act simultaneously</strong>?</div>',note('From high-dimensional pharmaceutical measurements to models that predict new observations.'),cls='title-slide')
add('Imagine 200 patients × 2,500 metabolites',eyebrow('LC–MS · hypothetical metabolomics study'),cards([('observed','Rows: 200 patients','Mild cognitive impairment at baseline; prospective follow-up.'),('model','Columns: 2,500 metabolites','Mass-spectrometry signals, intensities and derived features.'),('estimate','Outcome: progression','Could a metabolic fingerprint help predict Alzheimer’s progression over 3 years?')]),defn('A research objective, not a validated diagnostic test. A high-dimensional pattern can emerge only if we prevent information leakage and evaluate generalization.'))
add('The dimensionality is in the variables',eyebrow('High dimension ≠ extra physical dimensions'),figure('high_dimensional_matrices', 'Synthetic process and metabolomics matrices',tall='tall'),note('Every column is an independent measurement type; every row is a sampled observational unit.'))
add('Process analytical technology: why we care',eyebrow('Industrial pharmaceutical applications'),cards([('observed','Raw material fingerprints','Composition, supplier and batch variability.'),('model','Process conditions','Temperature, pressure, flow, particle size, spectroscopy.'),('estimate','Quality prediction','Potentially detect emerging deviations before a batch is lost.')]),'<div class="w12-hero" style="font-size:.76em;margin:.6em auto;">Too many measurements for a single-variable scatterplot.</div>')
add('Two different statistical questions',cards([('uncertainty','Structure discovery','How many useful dimensions? Are samples similar? Are there clusters?'),('estimate','Prediction','Can measured features predict a labeled future outcome?')]),flow([('Unsupervised','PCA, UMAP, clustering'),('Supervised','LDA, PLS, trees, neural networks')]),defn('Neither a visually attractive cluster nor a low training error proves a clinically useful pattern.'))
add('The challenge of high-dimensional data',eyebrow('Many variables · few patients'),cards([('observed','n = 200 patients','How much independent information can we learn?'),('warning','p = 2,500 variables','Correlations, multiple comparisons and overfitting multiply.'),('estimate','Need parsimonious structure','Dimension reduction, regularization and honest validation.')]))

# GAUSSIAN/DISTANCES
add('First, what does a distribution look like?',eyebrow('Two jointly continuous variables'),figure('gaussian_contours','Bivariate Gaussian covariance visualizations'),defn('A multivariate Normal distribution has a mean vector and covariance matrix. Covariance controls the orientation of its elliptical contours.'))
add('Lab: rotate a multivariate density',eyebrow('Interactive · change spread and correlation'),'<div class="w12-lab" id="gaussWidget"><div class="w12-controls"><label class="w12-control">distribution<select id="gaussMode"><option value="normal">one bivariate Normal</option><option value="mixture">two latent groups (mixture)</option></select></label><label class="w12-control">SD of X <strong id="gaussSxVal">1.30</strong><input id="gaussSx" type="range" min="0.5" max="2.0" step="0.05" value="1.30"></label><label class="w12-control">SD of Y <strong id="gaussSyVal">0.90</strong><input id="gaussSy" type="range" min="0.5" max="2.0" step="0.05" value="0.90"></label><label class="w12-control">correlation ρ <strong id="gaussRhoVal">0.45</strong><input id="gaussRho" type="range" min="-0.9" max="0.9" step="0.05" value="0.45"></label><div class="w12-micro">Drag the SVG to rotate the density surface. The two-group mixture is not a single Gaussian.</div></div><div class="w12-visual"><svg class="w12-svg rotate" id="gaussSvg" viewBox="0 0 900 490" aria-label="Interactive rotatable bivariate density surface"></svg></div></div>')
add('A mixture is not one Gaussian',eyebrow('The difference matters for interpretation'),cards([('model','Single multivariate Normal','One mode with covariance-defined elliptical contours.'),('uncertainty','Gaussian mixture','Two or more latent subpopulations create a weighted combination of densities.'),('warning','Beware hidden groups','A large overall covariance can be produced by mixing dissimilar populations.')]),formula(r'$f(x)=\pi f_1(x)+(1-\pi)f_2(x)$'))
add('What can pair plots still show?',eyebrow('Diagonal = distribution · below = association · above = coefficient'),figure('pairplot','Pairwise histograms, scatterplots and correlations from a synthetic four-marker dataset',tall='tall'),defn('Pairs plots remain useful for a modest number of variables; with 2,500 columns there are over three million distinct variable pairs.'))
add('Curse of dimensionality',eyebrow('Distance and density become harder to interpret'),cards([('warning','Distances may concentrate','Nearest and farthest points become harder to distinguish in some high-dimensional settings.'),('observed','Scaling determines geometry','A variable measured in large numerical units may dominate ordinary Euclidean distance.'),('estimate','Assumptions still matter','Feature selection, domain knowledge and task-specific metrics remain essential.')]))
add('Not every “distance” asks the same question',figure('distance_metrics','Euclidean Manhattan and cosine distances'),cards([('observed','Euclidean','Straight-line difference between standardized numerical profiles.'),('model','Manhattan','Absolute coordinate differences; emphasizes per-feature offsets.'),('uncertainty','Cosine','Difference of directions; useful for spectral profile shapes.')]))
add('Fingerprint overlap: Tanimoto similarity',eyebrow('Binary chemical fingerprints · bits for structural features'),figure('tanimoto_fingerprints','Two binary fingerprints with Tanimoto similarity'),defn('For binary fingerprints, the Tanimoto coefficient equals Jaccard similarity: number of features present in both divided by features present in at least one. Distance is one minus similarity.'))
add('Between groups: what does “close” mean?',figure('cluster_linkage','Illustrated single complete average and centroid linkage',tall='tall'),note('Single, complete, average and centroid linkages answer different questions. They may generate different hierarchical cluster trees.'))
add('A covariance-aware distance',eyebrow('Mahalanobis distance'),figure('mahalanobis','Mahalanobis distance follows ellipse covariance geometry'),formula(r'$d_M(x,\mu)=\sqrt{(x-\mu)^T\Sigma^{-1}(x-\mu)}$'),note('Different directions in the cloud are not equally surprising. A 2,500-variable covariance matrix cannot be inverted naively with only 200 patients.'))
add('A pharmaceutical distance problem',eyebrow('Identity checks · sample against chemical reference standard'),figure('ir_similarity','Synthetic infrared spectra comparing two samples to a reference'),defn('Spectral comparison needs baseline correction, alignment, appropriate scaling, and a similarity criterion. A metric threshold is not automatic proof of identity.'))
add('Multivariate tests exist—briefly',cards([('observed','Student t test','Compares one measured outcome.'),('uncertainty','Hotelling T²','Tests a multivariate mean difference under stronger covariance assumptions.'),('estimate','Our focus','Pattern recognition and prediction, not a catalogue of advanced multivariate tests.')]),note('With more variables than patients, the usual covariance estimate is singular; regularized approaches are needed.'))

# PCA SCALING
add('Before PCA: numerical scales are not neutral',eyebrow('New preprocessing slide · required for a meaningful PCA'),figure('pca_scaling','The same observations under unscaled, min-max normalized and z-score standardized PCA',tall='tall'),defn('PCA selects directions of maximum variance. Without scaling, high-variance units often dominate even when they are not scientifically more informative.'))
add('Two common scaling approaches',eyebrow('Transformation is not the same as dimension reduction'),cards([('observed','Min–max normalization',r'$x^{*}=(x-\min x)/(\max x-\min x)$ · maps observed training range to 0–1.'),('uncertainty','Z-score standardization',r'$z=(x-\bar x)/s$ · centers at 0 with training-set SD 1.')]),warn('Fit each scaling transform on training data only, then apply those same parameters to validation and test data. Min–max scaling is sensitive to extreme values.'))
add('PCA: find a new axis system',eyebrow('Principal component analysis · unsupervised'),cards([('observed','Inputs','A table of standardized metabolite intensities.'),('model','Orthogonal directions','PC1 captures the greatest remaining variance; PC2 is orthogonal and captures the next greatest.'),('estimate','Outputs','New score coordinates for patients + loadings describing each original variable.')]),formula(r'$\mathrm{PC}_1=a_1z_1+a_2z_2+\dots +a_pz_p$'))
add('Lab: rotate and find principal directions',eyebrow('3D → 2D projection with unknown group labels'),'<div class="w12-lab" id="pcaWidget"><div class="w12-controls"><div class="w12-micro">Rotate the three-dimensional point cloud. Try to retain maximum spread in your two-dimensional view; then reveal the mathematically optimal PCA plane.</div><div class="w12-btn-row"><button class="w12-btn" type="button" id="pcaShow">Show PCA</button><button class="w12-btn secondary" type="button" id="pcaReset">Explore again</button></div><div class="w12-output-row" style="--n:1;"><div class="w12-output"><span>Variance preserved in PC1 + PC2</span><strong id="pcaVar">—</strong></div><div class="w12-output"><span>View</span><strong id="pcaPlane">Custom viewpoint</strong></div></div><div class="w12-micro">Synthetic standardized hemoglobin, age and weight. The labels of underlying clouds are deliberately hidden.</div></div><div class="w12-visual"><svg id="pcaSvg" class="w12-svg rotate" viewBox="0 0 900 480" aria-label="Rotatable PCA point-cloud projection and variable loading vectors"></svg></div></div>')
add('Scores versus loadings',figure('pca_loadings_scree','PCA score plot and loading arrows with variance explained'),cards([('observed','Score','Patient coordinates in the new PC space.'),('model','Loading','How strongly the original variable contributes to the component.'),('uncertainty','Explained variance','How much total variance is captured, not automatically how much outcome information.')]))
add('PCA is blind to disease labels',eyebrow('Variance ≠ class separation'),cards([('warning','Wrong objective','"Choose the 2D view with the greatest separation between sick and healthy patients" is not PCA’s optimization goal.'),('estimate','Correct objective','Choose orthogonal directions with maximal retained data variance.'),('observed','Possible consequence','Class separation can emerge—but it can also hide in a low-variance direction.')]))
add('What is “information retained”?',eyebrow('Explained variance ratio'),formula(r'$\text{Variance retained by }k\text{ PCs}=\sum_{j=1}^k\lambda_j\big/\sum_{j=1}^p\lambda_j$'),defn('PCA compresses a dataset by sacrificing some of its variation. The lost variation can still contain clinically relevant information.'),note('In a 200 × 2,500 dataset, at most 199 centered directions can have nonzero sample variance.'))
add('A metabolomics PCA workflow',flow([('Prepare','Quality control; handling below-detection measurements'),('Transform','Appropriate intensity transform + training-only scaling'),('Project','Compute PC scores and loadings'),('Interpret','Check batch effects, biology and external datasets')]),warn('If PC1 separates instrument batches rather than patients, it may be revealing an unwanted technical artifact.'))
add('Factor analysis: a different goal',eyebrow('Latent shared sources of variation'),cards([('observed','PCA','Builds directions that describe variance in the observed data.'),('model','Factor analysis','Models covariance in observed variables as arising from a smaller set of latent factors plus variable-specific noise.'),('uncertainty','Interpretation','A factor named “inflammation” requires biological evidence; a latent-factor model does not establish causality.')]),formula(r'$\mathbf{x}=\mathbf{\Lambda}\mathbf{f}+\boldsymbol{\epsilon}$'))
add('Beyond straight-line projections',eyebrow('Neighborhood-based nonlinear dimension reduction'),cards([('observed','PCA','Linear projections; emphasizes global variance.'),('uncertainty','UMAP / related approaches','Seek neighborhood structure in a lower-dimensional map; adjustable neighborhood and spacing parameters.'),('warning','Projection ≠ proof','The exact shape, distances, and apparent clusters depend on method and settings.')]))
add('Neighborhoods can reshape a projection',eyebrow('Interactive Isomap illustration; conceptually related, not an actual UMAP implementation'),'<div class="w12-lab" id="nonlinearWidget"><div class="w12-controls"><label class="w12-control">neighborhood size<select id="nonlinK"><option value="7">7 nearest points</option><option value="16" selected>16 nearest points</option><option value="35">35 nearest points</option></select></label><div class="w12-micro">Precomputed Isomap neighborhoods at 7, 16, and 35 points. This is <strong>not</strong> UMAP and is labeled deliberately.</div></div><div class="w12-visual"><svg id="nonlinearSvg" class="w12-svg" viewBox="0 0 900 470" aria-label="Neighborhood embedding illustration"></svg></div></div>',note('For an exact UMAP exploration, the PAIR Understanding UMAP interactive can be opened separately when internet is available.'))
add('UMAP: what can go wrong visually?',figure('neighborhood_embedding','Isomap-based neighborhood illustration used to motivate UMAP',tall='short'),cards([('warning','Artificially separated islands','A two-dimensional projection may exaggerate distances or split connected structures.'),('estimate','Best interpretation','Local neighbors and stability across parameter settings are often more meaningful than global map geometry.')]))

# CLUSTERING
add('From compressed data to discovered groups',eyebrow('Unsupervised clustering'),cards([('observed','Input','Data with no known class labels.'),('model','Algorithm','Defines a notion of same-group membership.'),('estimate','Output','An assigned partition or cluster probabilities—not verified clinical diagnoses.')]))
add('Lab: three ways to find clusters',eyebrow('K-means, Gaussian mixture, and density-based clustering'),'<div class="w12-lab" id="clusterWidget"><div class="w12-controls"><label class="w12-control">point-cloud geometry<select id="clusterShape"><option value="moons">interlocking curved moons</option><option value="blobs">roughly Gaussian blobs</option></select></label><label class="w12-control">clustering method<select id="clusterMethod"><option value="kmeans">K-means</option><option value="gmm">Gaussian mixture</option><option value="dbscan">DBSCAN (density-based)</option></select></label><label class="w12-control">clusters k = <strong id="clusterKVal">2</strong><input id="clusterK" type="range" min="2" max="5" value="2" step="1"></label><label class="w12-control">DBSCAN radius<select id="clusterEps"><option value="0.14">0.14</option><option value="0.21" selected>0.21</option><option value="0.29">0.29</option><option value="0.38">0.38</option></select></label><div class="w12-output-row"><div class="w12-output"><span>Clusters found</span><strong id="clusterNum">—</strong></div><div class="w12-output"><span>Noise points</span><strong id="clusterNoise">—</strong></div></div></div><div class="w12-visual"><svg id="clusterSvg" class="w12-svg" viewBox="0 0 900 470" aria-label="Different clustering partitions of the same point cloud"></svg></div></div>')
add('K-means assumes compact groups',figure('clustering_methods','Compare three clustering methods applied to curved data'),defn('K-means minimizes within-cluster squared Euclidean distances from centroids. It can split curved shapes even when humans recognize two connected arcs.'))
add('A Gaussian mixture is a probability model',cards([('model','Each cluster has a density','The model estimates a mean, covariance and mixture weight for each component.'),('uncertainty','Assignment can be uncertain','Patients receive membership probabilities instead of only one hard label.'),('warning','Gaussian assumption','Skewed or winding clusters may not be represented well.')]))
add('DBSCAN: nearby density instead of k',cards([('observed','Core point','Enough observations within a chosen neighborhood radius.'),('estimate','Connected density','High-density regions grow into clusters; isolated observations can be called noise.'),('warning','Parameter sensitivity','The radius and minimum-neighbor settings determine which points are connected.')]),defn('HDBSCAN is a related more flexible approach that handles variable density and does not require a predefined number of clusters.'))
add('Clusters are hypotheses, not diagnoses',cards([('warning','Technical artifacts','Batch, instrument or site effects can masquerade as biological subtypes.'),('observed','Stability','Repeat on different samples and preprocessing choices.'),('estimate','External validity','Ask whether patterns replicate and predict clinically meaningful outcomes.')]))

# LEARNING
add('Statistical learning: make a useful function',eyebrow('From hand-written rules to fitted models'),figure('training_workflow','From problem framing to an untouched test set',tall='short'),defn('The goal is low expected loss on future observations, not perfect memorization of training measurements.'))
add('Three learning paradigms',cards([('observed','Unsupervised','Inputs X without known labels: PCA, clustering, density models.'),('estimate','Supervised','Labeled pairs (X, Y): classification of disease status or regression of concentration.'),('uncertainty','Reinforcement','Sequential actions with feedback and reward; important, but outside this course.')]))
add('What does the model actually learn?',formula(r'$\hat f = \arg\min_{f\in\mathcal F}\left\{\frac{1}{n}\sum_{i=1}^n L(y_i,f(x_i)) + \lambda\,\mathrm{penalty}(f)\right\}$'),cards([('observed','Empirical loss','How poorly do predictions agree with labeled training outcomes?'),('model','Model capacity','How flexible is the family of functions?'),('uncertainty','Regularization','How strongly should complexity be restrained?')]))
add('Keep evaluation honest',flow([('Training','Learn fitted parameters'),('Validation','Choose settings and features'),('Test','One final unbiased check on held-out patients')]),warn('All preprocessing, imputation, scaling, PCA and tuning must be fitted without seeing held-out test outcomes. Cross-validation can replace a simple validation split; use nested CV for unbiased evaluation when data are scarce.'))
add('A common pharmaceutical data leak',cards([('warning','Leakage','Scale all 200 patients, use all labels to screen 2,500 metabolites, then split data.'),('estimate','Correct method','Split first. Fit every learned preprocessing and feature-selection step within training folds.'),('observed','Even harder','Related patients, repeated visits and shared batches may require grouped splits.')]))
add('Now the labels are known',eyebrow('Supervised discriminative projections'),figure('pca_vs_lda','PCA versus LDA projection on labeled samples'),defn('LDA uses group labels to choose directions for class discrimination; PCA ignores labels and maximizes variance.'))
add('PLS: a different supervised projection',cards([('observed','X: spectra / metabolites','Hundreds of correlated predictors.'),('estimate','Y: outcome','Concentration for PLS regression; group-coded outcome for PLS discrimination variants.'),('uncertainty','Latent components','Find X directions covarying with the outcome; validate the chosen number of components.')]),note('LDA emphasizes group discrimination; PLS emphasizes predictor–response covariance. They are not interchangeable.'))
add('Decision trees turn thresholds into rules',figure('decision_tree','A three-level synthetic biomarker classification decision tree',tall='tall'),defn('Each internal node chooses a feature and threshold that reduces an impurity criterion, such as Gini impurity or entropy. Terminal nodes predict class proportions.'))
add('Lab: walk down a trained decision tree',eyebrow('Synthetic five-biomarker model · changing inputs changes the path'),'<div class="w12-lab" id="treeWidget"><div class="w12-controls">'+''.join(f'<label class="w12-control">{lab} = <strong id="treeV{i}">0.0</strong><input id="treeF{i}" type="range" min="-3" max="3" value="{[-.8,.3,1.5,-.1,.5][i]}" step="0.1"></label>' for i,lab in enumerate(['Amino acid A','Lipid B','Metabolite C','Amino acid D','Peptide E']))+'<div class="w12-output-row" style="--n:3;"><div class="w12-output"><span>Class</span><strong id="treePred">—</strong></div><div class="w12-output"><span>Leaf probability</span><strong id="treeProb">—</strong></div><div class="w12-output"><span>Rules used</span><strong id="treeDepth">—</strong></div></div></div><div class="w12-visual"><svg id="treeSvg" class="w12-svg" viewBox="0 0 900 510" aria-label="Decision path for a trained synthetic biomarker decision tree"></svg></div></div>')
add('A tree can memorize noise',eyebrow('The price of highly specific splitting'),cards([('observed','Shallow tree','Interpretable, but may miss real patterns.'),('warning','Fully grown tree','May fit incidental noise and batch artifacts.'),('estimate','Pruned tree','Limit depth/leaf size and validate on new observations.')]))
add('Random Forest: agreement across trees',figure('random_forest','Several decision trees combine votes to predict',tall='short'),defn('Train many diverse trees on bootstrap samples and subsets of predictors, then aggregate their predictions. A forest often has lower variance than a single unstable tree.'))
add('More trees are not more causal evidence',cards([('estimate','Predictive strength','Nonlinear interactions, complex class boundaries, variable importance estimates.'),('warning','Interpretability tradeoff','A high-performing predictor does not necessarily explain why a biomarker matters.'),('observed','Clinical requirements','Calibration, transportability, fairness, decision impact and prospective validation.')]))

# OVERFIT
add('Memorization versus generalization',eyebrow('The central machine-learning problem'),figure('bias_variance','Polynomial underfit good-fit overfit examples'),defn('A flexible model can fit all observed points while performing poorly on new measurements. Training error alone cannot detect that.'))
add('Bias–variance is a balance',cards([('observed','High bias · low flexibility','Misses the real trend: underfitting.'),('warning','High variance · high flexibility','Learns specific sample fluctuations: overfitting.'),('estimate','Lower future risk','Appropriate complexity, representative data and regularization.')]))
add('The interpolation threshold',eyebrow('When polynomial degree approaches number of points minus one'),formula(r'$n\text{ distinct }x\text{ values}\quad\Rightarrow\quad\text{degree }(n-1)\text{ polynomial can interpolate exactly.}$'),warn('Perfect interpolation says nothing by itself about performance between the observations or on patients from a new hospital.'))
add('Lab: polynomial complexity and double descent',eyebrow('A constructed, reproducible minimum-norm Legendre example'),'<div class="w12-lab" id="doubleWidget"><div class="w12-controls"><label class="w12-control">model assessment<select id="complexMode"><option value="train">training error only</option><option value="split" selected>training and validation errors</option></select></label><label class="w12-control">polynomial degree = <strong id="degreeVal">4</strong><input id="degree" type="range" min="1" max="44" value="4" step="1"></label><button id="complexResplit" type="button" class="w12-btn">Change training sample</button><div class="w12-output-row"><div class="w12-output"><span>Train MSE</span><strong id="complexTrain">—</strong></div><div class="w12-output"><span>Validation MSE</span><strong id="complexVal">—</strong></div></div><div class="w12-micro">14 training points from a cubic function + Gaussian noise. For degrees above 13, the Moore–Penrose minimum-coefficient-norm solution is used in the Legendre basis. Second descent is example-dependent, not guaranteed.</div></div><div class="w12-visual"><svg id="complexitySvg" class="w12-svg" viewBox="0 0 900 490" aria-label="Overparameterized polynomial fit with training and validation losses"></svg></div></div>')
add('Why can loss fall again?',cards([('warning','Near interpolation','Model may become numerically unstable: a validation-error peak.'),('uncertainty','Overparameterized side','Infinitely many interpolating functions can exist; the fitting rule selects one.'),('estimate','Implicit regularization','The minimum-norm solution may generalize better in some settings.')]),defn('Double descent does not replace the bias–variance idea, and adding parameters does not reliably improve future predictions.'))
add('A subtle reason to inspect the test set once',eyebrow('Selection can overfit the validation data, too'),flow([('Feature choice','Decided inside training/CV'),('Hyperparameters','Selected on validation/CV'),('Final test','Untouched independent evaluation'),('Real-world','Prospective and external replication')]),warn('Once you tune the model after examining test results, the test set has become part of training decisions.'))

# NEURAL
add('How do neural networks use predictors?',eyebrow('From regression to multilayer flexible mappings'),figure('single_neuron','Single artificial neuron weighted sum and activation',tall='short'),formula(r'$z=w_1x_1+\cdots+w_px_p+b\quad;\quad a=g(z)$'))
add('Animation: one artificial neuron',eyebrow('Five metabolites → one output'),video('perceptron'),note('This shows a weighted sum followed by an activation. Output probabilities require an appropriate output activation such as sigmoid or softmax.'))
add('A network is a composition of small functions',eyebrow('The nonlinear activations matter'),cards([('observed','Input layer','Features: metabolite abundance, age, treatment and so on.'),('model','Hidden layers','Many neurons with learned weights and nonlinear transformations.'),('estimate','Output layer','Class logits/probabilities or a continuous prediction, depending on task.')]),defn('Hidden activations need not be probabilities or be constrained between 0 and 1.'))
add('Animation: feedforward neural network',video('feedforward'),note('The animated 5 → 9 → 9 → 9 → 2 network is an illustrative teaching diagram, not the architecture of the digit predictor.'))
add('What makes a neural net flexible?',cards([('observed','Weights and biases','Parameters learned from labeled data.'),('uncertainty','Depth and width','Hyperparameters determining capacity and possible function shapes.'),('model','Activation functions','Nonlinearity enables curved and discontinuous-like decision boundaries.'),('warning','Capacity ≠ validity','A large model can learn artifacts as easily as meaningful signals.')]))
add('Training uses a loss function',eyebrow('Classification · compare truth and predicted probabilities'),formula(r'$L=-\sum_{k=1}^{K}\mathbf{1}\{Y=k\}\log \hat p_k$'),cards([('model','Forward pass','Compute predictions under current weights.'),('warning','Loss','Quantify prediction error on labeled examples.'),('estimate','Weight update','Change parameters to reduce the training objective.')]))
add('Animation: backpropagation',video('backpropagation'),note('Gradient information propagates backwards through the computation graph. This is a conceptual animation, not one-to-one measured neuron activations.'))
add('Training is more than one gradient step',flow([('Mini-batches','Sample labeled examples'),('Gradients','Backpropagate derivatives'),('Optimizer','Update model parameters'),('Epochs','Repeat while checking validation performance')]),defn('Validation data help tune architecture, regularization and early stopping; they are not a license to report training accuracy as deployment accuracy.'))
add('Convolutions learn local spatial patterns',eyebrow('Why images invite a different architecture'),cards([('observed','Image input','A 28 × 28 grid preserves spatial neighborhoods.'),('model','Convolution layers','Shared local filters produce spatial feature maps.'),('estimate','Classifier head','Combines features into a probability for each digit class.')]))
add('Animation: CNN concept',video('cnn_concept'),warn('The following digit classifier is an offline fully connected network, <strong>not a CNN</strong>. This animation explains how a CNN could process the same input, without pretending to show the predictor’s internal activations.'))
add('The famous handwritten-digit task',eyebrow('10 classes: 0, 1, …, 9'),cards([('observed','28 × 28 grayscale pixels','784 numerical input features.'),('model','Compact 784–96–48–10 MLP','ReLU hidden layers; final softmax across ten digit classes.'),('estimate','True offline inference','Bundled trained weights are evaluated locally in JavaScript—no external service.')]),note('Training provenance: scikit-learn handwritten digits (8×8 source images) enlarged and augmented to 28×28. The official MNIST dataset was unavailable at build time; no MNIST accuracy is claimed.'))
